// A failure in a node has execution.id (= the run id). A failure in the trigger has none: then trigger-<timestamp>.
const e = $input.first().json;
const ex = e.execution || {};
const id = ex.id != null && /^[A-Za-z0-9_-]{1,64}$/.test(String(ex.id)) ? String(ex.id) : 'trigger-' + Date.now();
return [{ json: { ...e, run_id: id, has_execution: ex.id != null } }];

const e = $('Error: ids').first().json;
const ex = e.execution || {};
const tr = e.trigger || {};
const err = ex.error || tr.error || {};
let pc = null;                                                                               // the live b-roll's pod clean-up (its own branch ran first), when it ran
try { pc = $('Error: record the pod clean-up').first().json.pod_cleanup || null; } catch (e) { pc = null; }
const data = {
  run_id: e.run_id, execution_id: ex.id != null ? String(ex.id) : null, failed_at: new Date().toISOString(),
  workflow: (e.workflow && e.workflow.name) || '', node: ex.lastNodeExecuted || (tr.error && tr.error.node && tr.error.node.name) || 'trigger',
  message: String(err.message || 'unknown error').slice(0, 1000),
};
if (pc) data.pod_cleanup = pc;
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(data, null, 1)), 'error.json', 'application/json');
return [{ json: data, binary: { data: bin } }];

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
const esc = (s) => String(s == null ? '' : s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
// never let a bot token reach run.json or a message, whatever the API echoes back
const scrub = (s) => String(s == null ? '' : s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, '***');
const errText = (e) => scrub(typeof e === 'string' ? e : (e && (e.description || e.message)) || 'unknown error');
// The chat id is the one thing kept outside the repo and outside n8n's credential: data/config/telegram.json, {"telegram_chat_id": "<digits>"}.
const chatIdFrom = async (ctx, input) => {
  if (!input || !input.binary || !input.binary.data) throw new Error('config/telegram.json was not read');
  let cfg;
  try { cfg = JSON.parse((await ctx.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); } catch (e) { throw new Error('config/telegram.json is not valid JSON'); }
  const id = String(cfg && cfg.telegram_chat_id != null ? cfg.telegram_chat_id : '').trim();
  if (!/^-?\d{1,20}$/.test(id)) throw new Error('config/telegram.json: telegram_chat_id must be digits');
  return id;
};
// The failure message: run, failing node, message (300 characters, token-scrubbed). Never throws: this workflow has no error workflow of its own.
try {
  const chat_id = await chatIdFrom(this, $input.first());
  const d = $('Error: build error.json').first().json;
  const text = 'ad-versions run ' + d.run_id + ' failed\nNode: ' + clip(scrub(d.node), 120) + '\n' + clip(scrub(d.message), 300) + (d.pod_cleanup ? '\nPod: ' + clip(scrub(d.pod_cleanup), 200) : '') + '\n(runs/' + d.run_id + '/error.json)';
  return [{ json: { chat_id, text: esc(text) } }];
} catch (e) {
  return [{ json: { error: clip(errText(e), 300) } }];
}

const clip = (s, n) => { s = String(s == null ? '' : s); return s.length > n ? s.slice(0, n - 1) + '…' : s; };
// never let a bot token reach run.json or a message, whatever the API echoes back
const scrub = (s) => String(s == null ? '' : s).replace(/bot\d+:[A-Za-z0-9_-]+/g, 'bot***').replace(/\d{6,}:[A-Za-z0-9_-]{20,}/g, '***');
const errText = (e) => scrub(typeof e === 'string' ? e : (e && (e.description || e.message)) || 'unknown error');
// error.json again, now saying whether the failure message went out (sent, failed: <reason>, or skipped: no chat id).
const d = $('Error: build error.json').first().json;
const T = $('Error: Telegram text').first().json;
const r = $input.first().json;
const why = (e) => (/^config\/telegram\.json/.test(e) ? 'no chat id' : clip(e, 200));       // chatIdFrom's own messages are the no-chat-id case; any other text-step failure keeps its reason
const telegram = T.error ? 'skipped: ' + why(T.error) : r.error ? 'failed: ' + clip(errText(r.error), 300) : 'sent';
const data = { ...d, telegram };
const bin = await this.helpers.prepareBinaryData(Buffer.from(JSON.stringify(data, null, 1)), 'error.json', 'application/json');
return [{ json: data, binary: { data: bin } }];

// Pod clean-up, step 1: what runs/<id>/pod.json says this run deployed (the pod's name once the toolkit accepted it; requested_at before that). Never throws.
try {
  const item = $input.first();
  if (!item || !item.binary || !item.binary.data) return [{ json: { cleanup: 'no pod to delete: this run deployed none (no pod.json)' } }];
  let d;
  try { d = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); } catch (e) { return [{ json: { cleanup: 'left alone: pod.json is not valid JSON' } }]; }
  const requested_ms = Number(d && d.requested_ms);
  const name = d && d.name ? String(d.name).slice(0, 80) : '';
  if (!name && !(requested_ms > 0)) return [{ json: { cleanup: 'left alone: pod.json names no pod and has no request time' } }];
  return [{ json: { pod_name: name, requested_ms } }];
} catch (e) {
  return [{ json: { cleanup: 'left alone: ' + String(e && e.message || e).slice(0, 150) } }];
}

// Pod clean-up, step 2: the toolkit's address from data/config/toolkit.json. Never throws: this workflow has no error workflow of its own.
try {
  const item = $input.first();
  if (!item || !item.binary || !item.binary.data) return [{ json: { cleanup: 'failed: config/toolkit.json was not read, the pod is left for the idle timer' } }];
  let cfg;
  try { cfg = JSON.parse((await this.helpers.getBinaryDataBuffer(0, 'data')).toString('utf8')); } catch (e) { return [{ json: { cleanup: 'failed: config/toolkit.json is not valid JSON' } }]; }
  const url = String(cfg && cfg.toolkit_url != null ? cfg.toolkit_url : '').trim().replace(/\/+$/, '');
  if (!/^https:\/\/[A-Za-z0-9.-]+(:\d{1,5})?$/.test(url)) return [{ json: { cleanup: 'failed: config/toolkit.json has no usable toolkit_url' } }];
  return [{ json: { toolkit_url: url } }];
} catch (e) {
  return [{ json: { cleanup: 'failed: ' + String(e && e.message || e).slice(0, 150) } }];
}

// Pod clean-up, step 3: is the pod on the Pods page the one pod.json says this run deployed? Delete only that one. A pod still `launching` cannot be deleted yet:
// ask again every 30 s for up to 10 minutes. Never throws.
try {
  const R = $('Error: pod record').first().json;
  let prev = {};
  try { prev = $('Error: wait to retry').last().json || {}; } catch (e) { prev = {}; }
  const attempt = Number(prev.attempt) || 0;
  const r = $input.first().json || {};
  const b = r.body || {};
  if (r.error || r.statusCode !== 200) return [{ json: { delete: false, retry: false, cleanup: 'failed: could not read the Pods page (' + (r.statusCode || 'no answer') + '), the pod is left for the idle timer' } }];
  const vm = b.vm;
  if (!vm) return [{ json: { delete: false, retry: false, cleanup: attempt ? 'pod gone' : 'no pod on the Pods page, nothing to delete' } }];
  const name = String(vm.name || '').slice(0, 60);
  const own = R.pod_name ? vm.name === R.pod_name : vm.kind !== 'build' && Number(vm.launched_at) * 1000 >= R.requested_ms - 5000;   // no name yet: the pod launched after the request
  if (!own) return [{ json: { delete: false, retry: false, cleanup: 'left alone: ' + name + ' was not deployed by this run' } }];
  if (vm.state === 'deleting') return [{ json: { delete: false, retry: false, cleanup: 'pod ' + name + ' is already being deleted' } }];
  if (vm.actions && vm.actions.delete === true) return [{ json: { delete: true, retry: false, pod: name } }];
  if (attempt >= 20) return [{ json: { delete: false, retry: false, cleanup: 'left for the idle timer: pod ' + name + ' was still ' + String(vm.state || '?').slice(0, 30) + ' after 10 minutes' } }];
  return [{ json: { delete: false, retry: true, attempt: attempt + 1, pod: name, state: String(vm.state || '?').slice(0, 30) } }];
} catch (e) {
  return [{ json: { delete: false, retry: false, cleanup: 'failed: ' + String(e && e.message || e).slice(0, 150) } }];
}

// Pod clean-up, last step: the outcome as one line (pod_cleanup), kept in error.json and the Telegram message. Never throws.
try {
  const d = $input.first().json || {};
  let pod_cleanup;
  if (d.cleanup) pod_cleanup = String(d.cleanup).slice(0, 200);
  else {
    let name = '';
    try { name = String($('Error: is there a pod to delete?').last().json.pod || ''); } catch (e) { name = ''; }
    const b = d.body || {};
    if (!d.error && d.statusCode === 200) pod_cleanup = 'deleted pod ' + name;
    else pod_cleanup = 'failed: the delete answered ' + (d.statusCode || 'nothing') + ' (' + String(b.error || (d.error && (d.error.message || d.error)) || 'no reason given').slice(0, 120) + '): delete it on the Pods page';
  }
  return [{ json: { pod_cleanup } }];
} catch (e) {
  return [{ json: { pod_cleanup: 'failed: ' + String(e && e.message || e).slice(0, 150) } }];
}
